\set ON_ERROR_STOP on

DO $fixture$
DECLARE source_type text; key text; answer_text text;
BEGIN
 FOREACH source_type IN ARRAY ARRAY['FORM','PDF','SPREADSHEET','WEBSITE'] LOOP
  key:=lower(source_type);
  answer_text:=CASE source_type WHEN 'FORM' THEN 'Form fact.' WHEN 'PDF' THEN 'PDF fact.' WHEN 'SPREADSHEET' THEN 'Spreadsheet fact.' ELSE 'Website fact.' END;
  UPDATE "KnowledgeEntry" SET "revisionState"='SEALED',"sealManifestHash"='http-seal-'||key,"sealPolicyVersion"='v1',"sealedAt"=clock_timestamp(),"sealedBy"='publisher',"updatedAt"=clock_timestamp() WHERE id='http-entry-'||key;
 END LOOP;
END $fixture$;

SELECT 'http-member-'||key,'http-property','http-publication','http-identity-'||key,'http-entry-'||key,'http-seal-'||key FROM unnest(ARRAY['form','pdf','spreadsheet','website']) key;
UPDATE "KnowledgePublication" SET state='SEALED',"sealedAt"=clock_timestamp(),"membershipClosedAt"=clock_timestamp() WHERE id='http-publication';
